                           ("sourceHashes", {}), ("payloadHashes", {}), ("pythonSha256", "0" * 64), ("coreZipSha256", "0" * 64),
                           ("coreInventorySha256", "0" * 64), ("versionResourceSha256", "0" * 64),
                           ("requestedCreateMode", 384), ("observedCreateMode", 420), ("newDirectoryMode", 448),
